package com.agacostays.billing.client;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import java.math.BigDecimal;
@Component public class BookingServiceClient{private final RestClient c;public BookingServiceClient(@Value("${service.booking.url}")String u,RestClient.Builder b){c=b.baseUrl(u).build();}public BookingSnapshot getBooking(Long id){try{Dto d=c.get().uri("/api/bookings/{id}",id).retrieve().body(Dto.class);return d==null?null:new BookingSnapshot(d.bookingId(),d.branchId(),d.customerId(),d.roomCharges(),d.bookingStatus());}catch(Exception e){return null;}}public record Dto(Long bookingId,Long branchId,Long customerId,BigDecimal roomCharges,String bookingStatus){}public record BookingSnapshot(Long bookingId,Long branchId,Long customerId,BigDecimal roomCharges,String bookingStatus){}}
